import{_ as t,a as r,b as i}from"./chunks/bubbles-03.CRJ58gUA.js";import{_ as e,o,c as n,a3 as s}from"./chunks/framework.D1iekJsc.js";const f=JSON.parse('{"title":"말풍선과 입력창","description":"MiniTavern 말풍선과 입력창 스타일. 테마를 따르거나 배경, 모서리, 나레이션·행동·대사 색, 블러를 따로 바꿉니다.","frontmatter":{"title":"말풍선과 입력창","description":"MiniTavern 말풍선과 입력창 스타일. 테마를 따르거나 배경, 모서리, 나레이션·행동·대사 색, 블러를 따로 바꿉니다.","head":[["meta",{"name":"keywords","content":"주점,AI 주점,MiniTavern,AI 파트너,AI 친구,AI 로컬 채팅,Silly Tavern,SillyTavern,모바일 Silly Tavern,Silly Tavern 모바일,Silly Tavern 안드로이드,Silly Tavern iOS,AI 롤플레이,캐릭터 카드,AI 채팅,모바일 AI,오프라인 AI,AI 스토리,로컬 LLM,Ollama,LM Studio,세계관,정규식,BYOK,사용자 가이드,매뉴얼"}],["meta",{"property":"og:title","content":"말풍선과 입력창 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern 말풍선과 입력창 스타일. 테마를 따르거나 배경, 모서리, 나레이션·행동·대사 색, 블러를 따로 바꿉니다."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ko/manual/bubbles"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ko/manual/bubbles"}]]},"headers":[],"relativePath":"ko/manual/bubbles.md","filePath":"ko/manual/bubbles.md","lastUpdated":1791862671000}'),l={name:"ko/manual/bubbles.md"};function g(c,a,p,u,h,d){return o(),n("div",null,[...a[0]||(a[0]=[s('<h1 id="말풍선과-입력창" tabindex="-1">말풍선과 입력창 <a class="header-anchor" href="#말풍선과-입력창" aria-label="Permalink to &quot;말풍선과 입력창&quot;">​</a></h1><p>경로: 하단 <strong>설정</strong> → <strong>채팅 설정</strong> → <strong>말풍선과 입력창</strong>.</p><p>여기서 바꾸는 것은 앱 전체의 채팅 모습입니다. 테마와 글자 크기는 <strong>설정 → 테마 및 글꼴</strong>에 있습니다.</p><h2 id="단계" tabindex="-1">단계 <a class="header-anchor" href="#단계" aria-label="Permalink to &quot;단계&quot;">​</a></h2><div class="shot-flow"><figure class="shot-step"><img src="'+t+'" alt="설정 홈"><figcaption>1 · 설정 → 채팅 설정</figcaption></figure><figure class="shot-step"><img src="'+r+'" alt="채팅 설정의 말풍선과 입력창"><figcaption>2 · 말풍선과 입력창</figcaption></figure><figure class="shot-step"><img src="'+i+'" alt="말풍선 색과 모서리"><figcaption>3 · 테마 따르기를 끄고 수정</figcaption></figure></div><h2 id="말풍선" tabindex="-1">말풍선 <a class="header-anchor" href="#말풍선" aria-label="Permalink to &quot;말풍선&quot;">​</a></h2><p><strong>말풍선</strong>과 <strong>입력창</strong>에는 각각 <strong>테마 따르기</strong>가 있습니다. 켜면 현재 테마를 씁니다. 끄면 아래 설정이 테마보다 우선하고, 비운 색은 테마를 그대로 씁니다.</p><ol><li><strong>AI 말풍선</strong>과 <strong>내 말풍선</strong>: 색상환입니다. 프리셋 색은 원이고, 고르면 체크가 붙습니다. 불투명도와 색 값을 바꿀 수 있고, 값은 복사할 수 있습니다. 줄에 「테마 색 사용」이 보이면 그 항목은 아직 테마를 따릅니다.</li><li><strong>모서리</strong>: 값이 클수록 더 둥급니다. 드래그한 뒤에는 테마 간격 대신 이 숫자를 씁니다.</li><li>글자색은 나뉩니다. <ul><li><strong>나레이션 글자</strong>와 나레이션 배경: 일반 본문과 굵은 글씨</li><li><strong>행동</strong>: <code>*별표*</code>로 감싼 글자</li><li><strong>대사</strong>: 따옴표 안</li><li>속마음</li></ul></li><li>카드가 이 기호를 쓰지 않아도 글자는 보이고, 나레이션 스타일로 나갑니다. HTML 카드 전체는 자기 색을 씁니다.</li></ol><h2 id="입력창" tabindex="-1">입력창 <a class="header-anchor" href="#입력창" aria-label="Permalink to &quot;입력창&quot;">​</a></h2><p>입력창의 <strong>테마 따르기</strong>를 끄면 배경, 모서리, 자리 표시자, 글자색, 버튼 아이콘, <strong>블러</strong>를 바꿀 수 있습니다.</p><p>블러를 켜면 색조와 강도를 조정합니다. API 31 미만 Android에는 이 스위치가 없습니다. iOS에서는 테마 따르기를 끈 뒤 블러가 기본으로 켜집니다.</p><h2 id="미리보기" tabindex="-1">미리보기 <a class="header-anchor" href="#미리보기" aria-label="Permalink to &quot;미리보기&quot;">​</a></h2><p>오른쪽 위 <strong>미리보기</strong>는 예시를 엽니다. 배경은 현재 언어의 여성 예시 카드이고, 예시 대화와 입력창이 있습니다. 마지막은 AI 메시지이며 이어하기, 스마트 답장 버튼이 있지만 눌러도 보내지 않습니다. 입력창도 보낼 수 없습니다. 왼쪽 버튼과 설정도 누르지 않습니다.</p><h2 id="관련" tabindex="-1">관련 <a class="header-anchor" href="#관련" aria-label="Permalink to &quot;관련&quot;">​</a></h2><ul><li><a href="./chat">채팅</a>: 말풍선 메뉴와 그 채팅의 설정</li><li><a href="./settings">설정</a>: 테마 및 글꼴</li></ul>',15)])])}const _=e(l,[["render",g]]);export{f as __pageData,_ as default};
